<!doctype html>
<html>
  <head>
    <meta charset="UTF-8" />
  </head>
  <body>
    <template>
      <style>
        @font-face { font-family: "Cormorant Garamond"; src: url("../assets/fonts/cormorant-garamond-italic.woff2") format("woff2"); font-weight: 300 700; font-style: italic; }
        #prologue-root { position: absolute; inset: 0; display: flex; align-items: center; justify-content: center; pointer-events: none; }
        #prologue-line { display: flex; gap: 32px; font-family: "Cormorant Garamond", serif; font-style: italic; font-weight: 500; font-size: 120px; color: #f3e6c4; text-shadow: 0 0 40px rgba(232, 197, 110, 0.35); }
        #prologue-line span { display: block; }
      </style>

      <div id="prologue-root" data-composition-id="prologue" data-width="1920" data-height="1080">
        <h1 id="prologue-line"><span>Ask</span><span>the</span><span>cards.</span></h1>
      </div>

      <script>
        (() => {
          const tl = gsap.timeline({ paused: true });
          const words = "#prologue-line span";
          tl.fromTo(words, { opacity: 0, y: 26, filter: "blur(14px)" }, { opacity: 1, y: 0, filter: "blur(0px)", duration: 0.75, ease: "power3.out", stagger: 0.16 }, 0.2);
          // The words drift apart as they dissolve.
          tl.to(words, { opacity: 0, x: (i) => (i - 1) * 34, filter: "blur(10px)", duration: 0.45, ease: "power2.in" }, 1.45);
          window.__timelines["prologue"] = tl;
        })();
      </script>
    </template>
  </body>
</html>
EOF
