p = "index.html"
s = open(p).read()
rep = [
 ("""          // The reading: a low glide across the glass.
          return tilt(inOutSine((t - CUT_READ) / (CUT_END - CUT_READ)));""",
  """          // The reading: a low, close glide across the glass.
          const e = inOutSine((t - CUT_READ) / (CUT_END - CUT_READ));
          const target = [0, lerp(1.2, -0.4, e), 0];
          return {
            items: [{ slot: 0, pos: [0, 0, 0], rot: [-0.06, lerp(0.3, 0.1, e), 0.05] }],
            cam: { pos: orbit(lerp(-30, -14, e), lerp(-12, -4, e), lerp(29, 25, e), target), target, fov: 28, roll: rad(lerp(-3, -1, e)) },
          };"""),
 ("const macro = shot(\"macro\"), reveal = shot(\"reveal\"), tilt = shot(\"tilt\");", "const macro = shot(\"macro\"), reveal = shot(\"reveal\");"),
 ('      tl.set("#halo", { x: -260 }, CUT_READ);\n', ''),
 ("uGain: { value: 1 }", "uGain: { value: 1.8 }"),
]
for a, b in rep:
    assert a in s, a
    s = s.replace(a, b)
open(p, "w").write(s)
EOF
